#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);root<-if(length(args))normalizePath(args[[1]])else normalizePath(".")
.libPaths(c(file.path(root,"project","Rlib-4.5"),file.path(root,"renv","library","macos","R-4.5","aarch64-apple-darwin20"),.libPaths()))
suppressPackageStartupMessages({library(data.table);library(ggplot2);library(patchwork)})
mr<-file.path(root,"project","results","mr");sg<-file.path(root,"project","results","shared_genetics");out<-file.path(root,"project","results","figures")
theme_pub<-theme_classic(base_size=7.2)+theme(plot.title=element_text(face="bold",size=8.5),plot.subtitle=element_text(size=6.3),axis.title=element_text(face="bold"),plot.margin=margin(5,6,5,5))
save_page<-function(p,stem,h=150){ggsave(file.path(out,paste0(stem,".pdf")),p,width=183,height=h,units="mm",device="pdf",useDingbats=FALSE,bg="white");ggsave(file.path(out,paste0(stem,".png")),p,width=183,height=h,units="mm",dpi=600,bg="white")}

# S5a: primary eGFRcrea diagnostics.
meth<-fread(file.path(mr,"main_mr_results.csv"));meth[,`:=`(lo=b-1.96*se,hi=b+1.96*se)];meth$method<-factor(meth$method,levels=rev(meth$method))
p1<-ggplot(meth,aes(b,method))+geom_vline(xintercept=0,colour="grey65")+geom_errorbarh(aes(xmin=lo,xmax=hi),height=.15)+geom_point(size=2,colour="#0072B2")+labs(tag="A",title="Primary method estimates",subtitle="Native log-odds scale; 264 instruments",x="MR estimate (95% CI)",y=NULL)+theme_pub
loo<-fread(file.path(mr,"leave_one_out.csv"));loo<-loo[SNP!="All"];setorder(loo,b);loo[,index:=.I];ivw<-meth[method=="Inverse variance weighted",b][1]
p2<-ggplot(loo,aes(index,b))+geom_hline(yintercept=ivw,colour="#D55E00",linewidth=.5)+geom_ribbon(aes(ymin=b-1.96*se,ymax=b+1.96*se),fill="grey80",alpha=.65)+geom_line(colour="#0072B2",linewidth=.35)+labs(tag="B",title="Leave-one-out estimates",subtitle="Each point omits one instrument; orange line is the full IVW estimate",x="Instrument ordered by omitted estimate",y="IVW estimate (95% CI)")+theme_pub
ss<-fread(file.path(mr,"single_snp.csv"));ss<-ss[!grepl("^All",SNP)];ss[,precision:=1/se]
p3<-ggplot(ss,aes(b,precision))+geom_point(size=.65,alpha=.55,colour="#0072B2")+geom_vline(xintercept=ivw,colour="#D55E00",linewidth=.5)+labs(tag="C",title="Single-instrument precision plot",subtitle="Descriptive funnel diagnostic; asymmetry is not a formal pleiotropy test",x="Single-instrument ratio estimate",y="Precision (1/SE)")+theme_pub
pagea<-(p1|p2)/p3+plot_annotation(title="Primary eGFRcrea Mendelian-randomization diagnostics",subtitle="Diagnostics qualify robustness but do not prove absence of pleiotropy or a causal effect",theme=theme(plot.title=element_text(face="bold",size=10),plot.subtitle=element_text(size=7)))+plot_layout(heights=c(1,1))
save_page(pagea,"Supplementary_Figure_S5a_primary_MR_diagnostics",165)

# S5b: expanded outcomes, retained as exploratory sensitivity analyses.
ex<-fread(file.path(mr,"expanded_outcomes","expanded_outcome_mr_results.csv"));ex[,`:=`(lo=b-1.96*se,hi=b+1.96*se)];ex$outcome_short<-ifelse(grepl("FinnGen",ex$outcome),"FinnGen thoracic aortic aneurysm","CHIP-MGI thoracic aortic aneurysm");ex$method<-factor(ex$method,levels=rev(unique(ex$method)))
p4<-ggplot(ex,aes(b,method,colour=outcome_short))+geom_vline(xintercept=0,colour="grey65")+geom_errorbarh(aes(xmin=lo,xmax=hi),height=.14,position=position_dodge(width=.35))+geom_point(position=position_dodge(width=.35),size=1.8)+scale_colour_manual(values=c("FinnGen thoracic aortic aneurysm"="#0072B2","CHIP-MGI thoracic aortic aneurysm"="#D55E00"))+labs(tag="A",title="Expanded-outcome method estimates",subtitle="Exploratory outcomes; not substitutes for the prespecified dissection outcome",x="MR estimate (95% CI)",y=NULL,colour=NULL)+theme_pub+theme(legend.position="bottom")
qc<-fread(file.path(mr,"expanded_outcomes","expanded_outcome_qc.csv"));qc[,outcome_short:=ifelse(grepl("FinnGen",outcome),"FinnGen thoracic aortic aneurysm","CHIP-MGI thoracic aortic aneurysm")];qc[,line:=paste0(outcome_short,"\n",harmonised_kept," harmonized instruments; mean F ",sprintf("%.1f",mean_F),"; minimum F ",sprintf("%.1f",min_F))];qc[,y:=rev(seq_len(.N))]
p5<-ggplot(qc,aes(.03,y,label=line))+geom_text(hjust=0,size=2.45,lineheight=.95)+xlim(0,1)+ylim(.5,2.5)+labs(tag="B",title="Expanded-outcome audit",subtitle="Outcome identity and instrument counts are retained in Source Data",x=NULL,y=NULL)+theme_void(base_size=7.2)+theme(plot.title=element_text(face="bold",size=8.5),plot.subtitle=element_text(size=6.3),plot.tag=element_text(face="bold",size=9))
pageb<-(p4/p5)+plot_annotation(title="Exploratory expanded aortic outcomes",subtitle="No expanded-outcome estimate is used to upgrade the renal-to-dissection causal claim",theme=theme(plot.title=element_text(face="bold",size=10),plot.subtitle=element_text(size=7)))+plot_layout(heights=c(3,1))
save_page(pageb,"Supplementary_Figure_S5b_expanded_outcomes",125)

# S5c: detailed genetic triangulation.
ld<-fread(file.path(sg,"ldsc","univariate_h2_qc.tsv"));ld[,trait:=factor(trait,levels=rev(trait))]
p6<-ggplot(ld,aes(h2_observed,trait,colour=qc_status))+geom_errorbarh(aes(xmin=ci_low,xmax=ci_high),height=.15)+geom_point(size=2)+scale_colour_manual(values=c(PASS="#009E73",CAUTION="#E69F00",BLOCK="#D55E00"))+labs(tag="A",title="Univariate LDSC quality control",subtitle="AAD Z=2.40<4 blocked bivariate genetic-correlation estimation",x="Observed-scale SNP heritability (95% CI)",y=NULL,colour="QC status")+theme_pub+theme(legend.position="bottom")
pri<-fread(file.path(sg,"coloc","coloc_abf_all_priors.tsv"));chr14<-pri[window_id%in%c("egfrcys_W042","cystatin_c_W097")];chr14$trait_label<-ifelse(chr14$trait=="egfrcys","eGFRcys","Serum cystatin C")
p7<-ggplot(chr14,aes(p12,PP.H4,colour=trait_label))+geom_hline(yintercept=.8,linetype="dashed",colour="grey55")+geom_line()+geom_point(size=1.7)+scale_x_log10()+scale_y_continuous(limits=c(0,1),breaks=seq(0,1,.2),expand=expansion(mult=c(0,.02)))+scale_colour_manual(values=c("eGFRcys"="#0072B2","Serum cystatin C"="#D55E00"))+labs(tag="B",title="Chromosome 14 prior sensitivity",subtitle="Overlapping samples; not independent replication",x="Shared-variant prior (p12)",y="PP.H4",colour=NULL)+theme_pub+theme(legend.position="bottom")
prim<-fread(file.path(sg,"coloc","coloc_primary_summary.tsv"));chr20<-prim[window_id%in%c("egfrcys_W087","cystatin_c_W188")];chr20$trait_label<-ifelse(chr20$trait=="egfrcys","eGFRcys","Serum cystatin C");long20<-melt(chr20,id.vars=c("trait_label","window_id"),measure.vars=c("PP.H3","PP.H4"),variable.name="hypothesis",value.name="posterior")
p8<-ggplot(long20,aes(posterior,trait_label,colour=hypothesis))+geom_point(size=2.3,position=position_dodge(width=.3))+scale_colour_manual(values=c("PP.H3"="#D55E00","PP.H4"="#0072B2"))+labs(tag="C",title="Chromosome 20 primary-prior result",subtitle="H3 favoured distinct variants under the fitted single-variant model",x="Posterior probability",y=NULL,colour=NULL)+theme_pub+theme(legend.position="bottom")
rev<-fread(file.path(sg,"coloc","reverse_mr_results.tsv"));rev[,display:=ifelse(status=="ESTIMABLE",sprintf("%s   %.3g [%.3g, %.3g]   q=%.3f   Phet=%.3g",trait,beta,ci_low,ci_high,q_bh,Q_p),sprintf("%s   1 instrument   UNDERIDENTIFIED",trait))];rev[,y:=rev(.I)]
p9<-ggplot(rev,aes(.02,y,label=display,colour=status))+geom_text(hjust=0,size=2.0)+xlim(0,1)+scale_colour_manual(values=c(ESTIMABLE="black",UNDERIDENTIFIED="#D55E00"),guide="none")+labs(tag="D",title="Reverse-MR detail",subtitle="Five outcomes each used two AAD instruments; beta scales differ",x=NULL,y=NULL)+theme_void(base_size=7.2)+theme(plot.title=element_text(face="bold",size=8.5),plot.subtitle=element_text(size=6.3),plot.tag=element_text(face="bold",size=9))
pagec<-(p6|p7)/(p8|p9)+plot_annotation(title="Detailed genetic-triangulation diagnostics",subtitle="QC failure, prior sensitivity, regional model dependence and limited instruments remain distinct evidence states",theme=theme(plot.title=element_text(face="bold",size=10),plot.subtitle=element_text(size=7)))
save_page(pagec,"Supplementary_Figure_S5c_genetic_triangulation",155)

# Source package.
fwrite(meth,file.path(out,"Supplementary_Figure_S5a_source_data_methods.tsv"),sep="\t");fwrite(loo,file.path(out,"Supplementary_Figure_S5a_source_data_leave_one_out.tsv"),sep="\t");fwrite(ss,file.path(out,"Supplementary_Figure_S5a_source_data_single_snp.tsv"),sep="\t")
fwrite(ex,file.path(out,"Supplementary_Figure_S5b_source_data_expanded_outcomes.tsv"),sep="\t");fwrite(qc,file.path(out,"Supplementary_Figure_S5b_source_data_qc.tsv"),sep="\t")
fwrite(ld,file.path(out,"Supplementary_Figure_S5c_source_data_ldsc.tsv"),sep="\t");fwrite(chr14,file.path(out,"Supplementary_Figure_S5c_source_data_chr14.tsv"),sep="\t");fwrite(long20,file.path(out,"Supplementary_Figure_S5c_source_data_chr20.tsv"),sep="\t");fwrite(rev,file.path(out,"Supplementary_Figure_S5c_source_data_reverse_mr.tsv"),sep="\t")
idx<-data.frame(page=c("S5a","S5b","S5c"),visual_file=c("Supplementary_Figure_S5a_primary_MR_diagnostics.pdf","Supplementary_Figure_S5b_expanded_outcomes.pdf","Supplementary_Figure_S5c_genetic_triangulation.pdf"),claim_ids=c("C4 context","C4 context","C12-C15"),boundary=c("Diagnostics do not prove no pleiotropy or no effect","Exploratory outcomes do not replace aortic dissection","Distinct QC/prior/model/instrument limitations"))
fwrite(idx,file.path(out,"Supplementary_Figure_S5_source_data.tsv"),sep="\t");writeLines(capture.output(sessionInfo()),file.path(out,"Supplementary_Figure_S5_sessionInfo.txt"));cat("SUPPLEMENTARY_FIGURE_S5_COMPLETE\n")
